/* A store's team. A new server only table `store_team_members`: one row per person the owner invites to their store (Settings > Team), with the email it was sent to, the role (manager or staff), whether they have accepted (invited, then active once they open the link signed in with their own Storelib account, which sets user_id), who sent it and when, and the invite link's token kept only as its SHA-256 (the link itself is in the email and nowhere else). One row per email per store. Only the service role reads or writes it: no policy for visitors or signed in users, so a member can never list a team or change a role from the browser; every check goes through the server (lib/team). Changes no existing row. Until it runs, Settings > Team says the team is not set up yet and everything else works as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'store team: there is no creators table yet.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.store_team_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, email text NOT NULL, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL, status text NOT NULL DEFAULT 'invited', token_hash text, invited_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, invited_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, accepted_at timestamptz, CONSTRAINT store_team_members_role_check CHECK (role IN ('manager', 'staff')), CONSTRAINT store_team_members_status_check CHECK (status IN ('invited', 'active')), CONSTRAINT store_team_members_email_check CHECK (email = lower(email) AND char_length(email) BETWEEN 3 AND 254 AND position('@' in email) > 1), CONSTRAINT store_team_members_active_user CHECK (status <> 'active' OR user_id IS NOT NULL), CONSTRAINT store_team_members_one_email UNIQUE (creator_id, email)); CREATE UNIQUE INDEX IF NOT EXISTS store_team_members_token_idx ON public.store_team_members (token_hash) WHERE token_hash IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS store_team_members_one_user ON public.store_team_members (creator_id, user_id) WHERE user_id IS NOT NULL; CREATE INDEX IF NOT EXISTS store_team_members_user_idx ON public.store_team_members (user_id) WHERE user_id IS NOT NULL; ALTER TABLE public.store_team_members ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_team_members FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_team_members TO service_role; END $do$;
notify pgrst, 'reload schema';
